import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات منح درجة البكالوريوس في تخصص طب وجراحة الأسنان"
save("0218",N,[
("rule",[14],"المادة 20 (أ)","يفصل طالب طب وجراحة الأسنان من الكلية إذا لم يجتز أي سنة من السنوات الأربع الأولى في مدة سنتين جامعيتين، أو لم يجتز السنة الخامسة في ثلاث سنوات جامعية، أو لم يكمل دراسته خلال ثماني سنوات، أو رسب في أي أربع سنوات دراسية خلال مدة دراسته في الكلية.",
 "ما حالات الفصل من كلية طب الأسنان؟","هل يفصل طالب طب الأسنان إذا رسب أربع سنوات دراسية؟","بنفصل من طب الأسنان إذا قضيت ثماني سنين؟"),
("rule",[14],"المادة 20 (ج، د)","تصدر قرارات الفصل من الكلية أو الجامعة عن مجلس العمداء بتنسيب من مجلس الكلية، وتشعر وحدة القبول والتسجيل الطالب إلكترونياً على آخر عنوان إلكتروني له. وإذا فصل الطالب من الكلية استناداً للمادة 20 (أ) أو (ب) وكان مفصولاً سابقاً يفصل من الجامعة نهائياً ولا يجوز له العودة إليها.",
 "ماذا يحدث لطالب طب الأسنان المفصول للمرة الثانية؟","كيف يبلغ طالب طب الأسنان بقرار الفصل؟","إذا انفصلت مرتين من طب الأسنان بنفصل من الجامعة؟"),
("rule",[14],"المادة 20 (هـ/2)","يحق لطالب طب وجراحة الأسنان المفصول من الفئة (أ) أن يستمر في نفس التخصص ضمن الفئة (ب) ويعطى سنة دراسية إضافية لاحقة دون انقطاع (ويجوز التأجيل أو الانسحاب للسنة الإضافية) لإزالة أسباب الفصل أو إنهاء متطلبات الدرجة، وإذا لم يتمكن من إزالة الأسباب يفصل من التخصص.",
 "هل يعطى طالب طب الأسنان المفصول سنة إضافية؟","ماذا يحدث إذا لم يزل طالب طب الأسنان أسباب فصله خلال السنة الإضافية؟","انفصلت من طب الأسنان، في فرصة أستمر؟"),
("rule",[14],"المادة 20 (هـ/3، هـ/4، هـ/5)","لا يجوز للطالب المفصول بسبب تجاوزه الحد الأعلى لسنوات الدراسة في طب الأسنان الحصول على فرصة السنة الإضافية أكثر من مرة، ولا يجوز الحصول عليها أكثر من مرتين متتاليتين. وتستوفى الرسوم حسب الرسوم المقررة في الفصل الذي تم فيه الحصول على السنة الإضافية.",
 "كم مرة يحصل طالب طب الأسنان على فرصة السنة الإضافية؟","بأي رسوم تحسب السنة الإضافية في طب الأسنان؟","كم مرة بتعطوني سنة إضافية بطب الأسنان؟"),
("rule",[14],"المادة 20 (هـ/1)","المقصود بأبناء العاملين في جدول فئات الرسوم لطلبة طب الأسنان هم أبناء العاملين في جامعة العلوم والتكنولوجيا الأردنية وجامعة اليرموك ومستشفى الملك المؤسس عبدالله الجامعي.",
 "من هم أبناء العاملين في جدول الرسوم لطلبة طب الأسنان؟","هل أبناء العاملين في جامعة اليرموك يشملهم جدول الرسوم في طب الأسنان؟","مين بنحسب من أبناء العاملين بطب الأسنان؟"),
("number",[15],"المادة 21 (أ/1، أ/3)","لا تؤجل دراسة الطالب المستجد في كلية طب الأسنان أو المنتقل إليها إلا بعد مضي سنة دراسية واحدة على الأقل على دراسته فيها. ويجوز التأجيل مدة لا تزيد عن سنتين دراسيتين متلاحقتين أو منفصلتين، وتصل إلى ثلاث سنوات كحد أعلى بقرار من مجلس الكلية، ولا تحسب مدة التأجيل من الحد الأعلى لمدة الدراسة.",
 "كم سنة يجوز لطالب طب الأسنان تأجيل دراسته؟","هل يجوز تأجيل الدراسة للطالب المستجد في طب الأسنان؟","كم سنة بقدر أأجل بطب الأسنان؟"),
("number",[15],"المادة 21 (أ/2، أ/4)","لا تؤجل الدراسة لطالب طب الأسنان الذي لديه مساقات نتيجتها غير مكتملة إلا بعد إكمالها وإلا ترصد له علامة الأعمال الفصلية فقط. وإذا لم يسجل طالب منتظم لفصل ولم يتقدم بطلب تأجيل خلال (14) أسبوعاً من بداية الفصل الأول (أو الثاني للسنوات ما قبل السريرية) يعتبر مؤجلاً لسنة حكماً، وفي السنوات السريرية خلال (10) أسابيع من بداية الفصل الثاني. وإذا تجاوز مدة التأجيل يفقد مقعده.",
 "خلال كم أسبوع يقدم طالب طب الأسنان طلب التأجيل وإلا يعتبر مؤجلاً حكماً؟","هل يفقد طالب طب الأسنان مقعده إذا تجاوز مدة التأجيل؟","ما قدمت طلب تأجيل بطب الأسنان، شو بصير؟"),
("rule",[15],"المادة 21 (أ/7، أ/8، أ/9)","لا تحسب السنة الدراسية التي يفصل منها طالب طب الأسنان بسبب عقوبة تأديبية من الحد الأعلى لمدة الدراسة أو التأجيل. ويجوز للطالب المحول أو الراسب فصلاً واحداً التأجيل في حال عدم وجود مواد علمية يدرسها حسب خطته دون احتسابه من الحد الأعلى. ويجوز لطالب إحدى السنوات الثلاث الأولى المؤجل من الفصل الثاني والراسب بالسنة بنتائج الفصل الأول إلغاء تأجيله والتسجيل للفصل الأول اللاحق معيداً للسنة.",
 "هل تحسب سنة الفصل التأديبي من الحد الأعلى لمدة الدراسة في طب الأسنان؟","هل يجوز لطالب طب الأسنان إلغاء التأجيل بعد الرسوب بنتائج الفصل الأول؟","انفصلت تأديبي من طب الأسنان، بتنحسب السنة من المدة؟"),
("rule",[15],"المادة 21 (ب)","يجوز لطالب طب الأسنان الفاقد لمقعده التقدم بطلب جديد للالتحاق: إذا قبل في نفس تخصصه والخطة التي قبل عليها وكانت فعالة يحتفظ بسجله الأكاديمي كاملاً وتحسب مدة دراسته السابقة ضمن الحد الأعلى، وإلا تطبق عليه المادة (24). ولا يجوز احتساب السجل الأكاديمي إذا انقطع أربع سنوات فأكثر. ومن لم يسجل للفصل الأول لقبوله ولم ينسحب يعتبر مستنكفاً.",
 "ماذا يحدث للسجل الأكاديمي لطالب طب الأسنان الفاقد لمقعده إذا أعيد قبوله؟","بعد كم سنة انقطاع لا يحتسب السجل الأكاديمي في طب الأسنان؟","فقدت مقعدي بطب الأسنان ورجعت قدمت، علاماتي بتضل؟"),
("rule",[15],"المادة 21 (ج)","إذا رغب طالب طب الأسنان في الانسحاب من الجامعة فعليه تقديم طلب إلكتروني فتثبت له ملاحظة «منسحب من الجامعة» ويفقد مقعده، وعند رغبته بالالتحاق ثانية تطبق عليه أحكام (21/ب/1 و2). ولا يجوز لمن لديه مساقات غير مكتملة الانسحاب إلا بعد إكمالها وإلا ترصد له علامة الأعمال الفصلية.",
 "كيف ينسحب طالب طب الأسنان من الجامعة؟","هل يجوز الانسحاب من الجامعة لمن لديه مساق غير مكتمل في طب الأسنان؟","بدي أنسحب من الجامعة وأنا بطب أسنان، كيف؟"),
("rule",[15],"المادة 22","تتم إجراءات تغيير التخصص لطلبة طب وجراحة الأسنان وفق أسس تغيير التخصص المقرة والمعمول بها في الجامعة.",
 "كيف يتم تغيير التخصص لطلبة طب وجراحة الأسنان؟","وفق أي أسس يغير طالب طب الأسنان تخصصه؟","بقدر أغير تخصصي من طب الأسنان؟"),
("rule",[16],"المادة 23","شروط انتقال الطالب إلى الجامعة من جامعة أردنية رسمية على البرنامج العادي: أن يكون مقبولاً ضمن قوائم وحدة تنسيق القبول الموحد، وأن تنطبق عليه إحدى حالتين: إصابته بمرض (السرطان قيد العلاج الكيماوي أو الإشعاعي، أو الفشل الكلوي المزمن الذي يستدعي غسيلاً منتظماً، أو أمراض الدماغ والأعصاب التي تؤدي إلى شلل لا يرجى شفاؤه) بتقارير طبية معتمدة وموافقة اللجنة الطبية العليا ومجلس العمداء، أو القضايا العشائرية التي تستدعي الجلوة بكتاب من الحاكم الإداري ويكون الانتقال مؤقتاً لفصل قابل للتجديد.",
 "ما شروط الانتقال من جامعة أردنية رسمية إلى جامعة العلوم والتكنولوجيا على البرنامج العادي؟","ما الأمراض التي تجيز الانتقال إلى الجامعة من جامعة رسمية أخرى؟","بقدر أنتقل لجامعة العلوم من جامعة ثانية إذا عندي مرض مزمن؟"),
("rule",[16],"المادة 23 (ثانياً/2)","في حالة القضايا العشائرية التي تستدعي الجلوة، يكون انتقال الطالب إلى الجامعة مؤقتاً لمدة فصل دراسي واحد قابل للتجديد بكتاب من الحاكم الإداري في اللواء، وإذا استمرت القضية واجتاز الطالب أكثر من 50% من الخطة الدراسية في الجامعة أو وصل إلى فصل التخرج يمكن منحه الدرجة العلمية من جامعة العلوم والتكنولوجيا.",
 "كم مدة الانتقال المؤقت بسبب القضايا العشائرية إلى الجامعة؟","هل يمكن منح الدرجة من الجامعة لمن انتقل بسبب قضية عشائرية؟","انتقلت للجامعة بسبب جلوة عشائرية، بقدر أتخرج منها؟"),
("rule",[17],"المادة 24","إذا قبل الطالب في طب وجراحة الأسنان وكان قد درس مساقات في كلية أو قسم آخر من نفس الجامعة، عليه إجراء احتساب المساقات عبر بوابة خدمات الطالب الإلكترونية قبل تسجيل مساقات فصل القبول، باختيار إحدى حالتين: احتساب جميع المساقات الناجحة التي تدخل ضمن خطة التخصص مع دخول نقاطها في معدله السنوي، أو معاملته كطالب مستجد دون احتساب أي مساق. وإذا لم يتقدم خلال المدة المحددة تطبق عليه الحالة الثانية.",
 "كيف تحتسب المساقات المدروسة داخل الجامعة لطالب انتقل إلى طب الأسنان؟","ماذا يحدث إذا لم يقدم طلب احتساب المساقات داخل الجامعة عند الانتقال لطب الأسنان؟","كنت بتخصص ثاني وانتقلت لطب أسنان، كيف بتنحسب موادي؟"),
("number",[17],"المادة 24 (ب)","يختار عميد كلية طب الأسنان الخطة الدراسية المناسبة للطالب المنتقل (من الخطط الفعالة) في موعد أقصاه أسبوعان من بداية فصل قبوله، ويحدد مستواه إذا حقق شرطين: إمكانية تسجيل الساعات العلمية المتبقية من المستويات الأقل مع مساقات المستوى الجديد دون تعارض مع المادة (7/د)، وعدم رسوبه سابقاً بالمساقات العلمية المتبقية.",
 "من يحدد الخطة الدراسية ومستوى الطالب المنتقل إلى طب الأسنان؟","خلال كم أسبوع يحدد العميد مستوى الطالب المنتقل لطب الأسنان؟","مين بحدد مستواي بطب الأسنان بعد الانتقال؟"),
("number",[18],"المادة 25","يتقدم الطالب بطلب معادلة المساقات التي درسها خارج الجامعة خلال أسبوعين من بدء الفصل الدراسي الأول لقبوله، وتشكل كلية طب الأسنان لجنة معادلة المساقات، ويبت العميد بالمساقات المعادلة خلال أسبوعين من تقديم الطلب ثم ترسل إلى وحدة القبول والتسجيل.",
 "خلال كم أسبوع يقدم طالب طب الأسنان طلب معادلة المساقات من خارج الجامعة؟","كم أسبوعاً يستغرق قرار العميد بالمساقات المعادلة في طب الأسنان؟","امتى لازم أقدم طلب معادلة مواد بطب الأسنان؟"),
("rule",[18],"المادة 25 (أ)","تعادل المساقات التي درسها الطالب قبل قبوله في الجامعة (في جامعة أو كلية معترف بها) إذا تحقق: عدد ساعات المساق الخارجي يساوي أو يزيد عن الداخلي (مع إمكانية دمج مساقين)، والتكافؤ في مخرجات التعلم بنسبة لا تقل عن 80% حسب تقدير لجنة المعادلة، والنجاح فيه في المؤسسة التي درسه فيها. ويجوز لعميد الكلية إعفاؤه من مساق واحد على الأكثر من مساقات الجامعة الاختيارية إذا درس مساقاً قبل قبوله ولم تتم معادلته.",
 "ما شروط معادلة مساق درسه الطالب قبل قبوله في طب الأسنان؟","ما نسبة التكافؤ المطلوبة لمعادلة المساقات من خارج الجامعة؟","درست مادة بجامعة ثانية، كيف بتنعادل ببكالوريوس طب الأسنان؟"),
("rule",[19],"المادة 25 (ب)","إذا رغب طالب طب الأسنان في دراسة مساق خلال الفصل الصيفي في جامعة أخرى فعليه الحصول على موافقة مسبقة من عميد كليته بالتنسيق مع عميد الكلية التي تطرح المساق، بشروط: المساق غير مطروح صيفاً أو يوجد تعارض لا يحل، وعدد ساعاته يساوي أو يزيد عن الأصلي، وتكافؤ مخرجات التعلم 80% فأكثر، وألا يتجاوز مجموع المسجل العبء المسموح، والنجاح فيه، وعدم دراسته أو مكافئه سابقاً في الجامعة أو الرسوب به.",
 "ما شروط دراسة مساق صيفي في جامعة أخرى لطالب طب الأسنان؟","هل يجوز لطالب طب الأسنان أن يدرس مساقاً صيفياً في جامعة ثانية؟","بقدر أدرس مادة بالصيف بجامعة ثانية وأنا بطب أسنان؟"),
("rule",[19],"المادة 25 (ج، د)","يعفى الطالب من المساقات المقبولة للمعادلة والتي درسها خارج الجامعة ولا تدخل ضمن معدله السنوي. ولا يجوز احتساب الساعات المعتمدة للطلبة الذين يدرسون في جامعة أخرى خلال فترة تأجيل دراستهم أو انسحابهم أو فقدانهم لمقاعدهم.",
 "هل تدخل المساقات المعادلة من خارج الجامعة في المعدل السنوي في طب الأسنان؟","هل تحتسب الساعات المدروسة في جامعة أخرى أثناء التأجيل في طب الأسنان؟","درست بجامعة ثانية وأنا مؤجل، بتنحسب؟"),
("rule",[20],"المادة 26","يكون المساق مكافئاً لمساق آخر إذا ورد ذلك في الخطة الدراسية أو الخطة الانتقالية أو كان محتواه مطابقاً لمحتوى مساق في كلية أخرى. ويجوز تسجيل المكافئ بدلاً من الأصيل بموافقة عميد كلية الطالب بالتنسيق مع عميد الكلية التي تطرح المساق إذا كان الأصيل غير مطروح أو وجد تعارض لا يمكن حله، ويجب أن يساوي المكافئ الأصيل بعدد الساعات أو يزيد.",
 "متى يكون المساق مكافئاً لمساق آخر في طب الأسنان؟","متى يجوز تسجيل المساق المكافئ بدلاً من الأصيل؟","متى بقدر آخد مادة مكافئة بدل المادة الأصلية؟"),
("number",[20],"المادة 27","يحسب المعدل العام والحد الأعلى لمدة الدراسة للطالب المعفى من سنة من السنوات الثلاث الأولى في طب الأسنان كما يلي: 22% لكل سنة من السنوات المتبقية عدا الخامسة و34% للسنة الخامسة، والحد الأعلى للدراسة (7) سنوات. وللمعفى من سنتين: 30% لكل سنة متبقية عدا الخامسة و40% للسنة الخامسة، والحد الأعلى (6) سنوات.",
 "كم الحد الأعلى لمدة الدراسة للطالب المعفى من سنة دراسية في طب الأسنان؟","كيف يحسب المعدل العام للطالب المعفى من سنتين في طب الأسنان؟","انعفيت من سنة بطب الأسنان، كم بصير الحد الأعلى للدراسة؟"),
("rule",[21],"المادة 28 و29","تمنح درجة البكالوريوس في طب وجراحة الأسنان بعد: النجاح في جميع مساقات الخطة، ومعدل عام لا يقل عن (2.00)، وعدم تجاوز الحد الأعلى لمدة الدراسة، وأن يسجل طالباً منتظماً في آخر ثلاث سنوات دراسية بما فيها سنة التخرج. ويجوز بموافقة العميد تأجيل التخرج لفصل دراسي واحد فقط (بما فيه الصيفي) لرفع المعدل العام.",
 "ما شروط التخرج من تخصص طب وجراحة الأسنان؟","هل يجوز تأجيل التخرج لرفع المعدل في طب الأسنان؟","شو شروط التخرج بطب الأسنان وبقدر أأجل تخرجي؟"),
("rule",[21],"المادة 30 و31","تمنح شهادات التخرج عند استحقاقها في نهاية كل فصل دراسي، ويقام حفل التخريج مرتين في العام: الأول بعد نهاية الفصل الأول والثاني بعد نهاية الفصل الثاني. وتصدر وثائق التخريج للعرب باللغة العربية ولغير العرب بالإنجليزية، والعربية اختيارية لهم.",
 "كم مرة يقام حفل التخريج في العام الجامعي؟","بأي لغة تصدر وثائق التخريج للطلبة غير العرب؟","امتى بيصير حفل التخريج وبأي لغة الشهادة؟"),
("rule",[22],"المادة 32 إلى 38","يكلف عميد الكلية مرشداً أكاديمياً من أعضاء هيئة التدريس لكل طالب، والعميد والمرشد مسؤولان عن متابعة سير الطالب والتحقق من استيفائه شروط التخرج، وعلى المرشد إبلاغ الطالب سنوياً. وعلى الطالب الحصول على براءة ذمة لإكمال إجراءات تخرجه، وتحمل الدرجة تاريخ استحقاقها، ولا يجوز الاعتراض بعدم العلم بالتعليمات، ويبت مجلس العمداء في الحالات التي لم يرد فيها نص. ومن أراد دراسة بكالوريوس آخر تطبق عليه تعليمات البكالوريوس الإضافي.",
 "من يتابع السير الأكاديمي لطالب طب الأسنان؟","هل يجوز للطالب الاعتراض بعدم علمه بالتعليمات؟","لازم أحصل على براءة ذمة عشان أتخرج؟"),
],"d",verified="text")
